מב. עִקַּר הַבְּרִיאָה הוּא רַק בִּשְׁבִיל הָאֱמֶת, כְּמוֹ שֶׁכָּתוּב: "בְּרֵאשִׁית בָּרָא אֱלֹקִים אֵת וְגוֹ'", וְדָרְשׁוּ רַבּוֹתֵינוּ זַ"ל שֶׁסּוֹפֵי־תֵבוֹת - "אֱמֶת", שֶׁבּוֹ נֶחְתְּמוּ שָׁמַיִם וָאָרֶץ. כִּי הַקָּדוֹשׁ־בָּרוּךְ־הוּא עֶצֶם הָאֱמֶת, וְחוֹתָמוֹ אֱמֶת, וְעִקַּר הִשְׁתּוֹקְקוּתוֹ יִתְבָּרַךְ הוּא רַק אֶל הָאֱמֶת, וְכָל הַבְּרִיאָה כֻּלָּהּ מֵרֹאשׁ וְעַד סוֹף הוּא רַק בִּשְׁבִיל זֶה כְּדֵי לְגַלּוֹת הָאֱמֶת, כְּמוֹ שֶׁאָמְרוּ בַּזֹּהַר הַקָּדוֹשׁ, שֶׁהַבְּרִיאָה הָיְתָה "בְּגִין דְּיִשְׁתְּמוֹדְעִין לֵהּ", שֶׁזֶּהוּ עִקַּר הָאֱמֶת שֶׁיַּכִּירוּ וְיֵדְעוּ אֲמִתַּת אֱלָקוּתוֹ יִתְבָּרַךְ כְּמוֹ שֶׁהוּא בֶּאֱמֶת; כִּי הַשֵּׁם יִתְבָּרַךְ עֶצֶם הָאֱמֶת כִּבְיָכוֹל. אַךְ מֵחֲמַת שֶׁהָעוֹלָמוֹת אִי אֶפְשָׁר לָהֶם לִסְבֹּל וּלְקַבֵּל עֶצֶם אוֹר הָאֱמֶת, כִּי יִתְבַּטְּלוּ בַּמְּצִיאוּת, עַל־כֵּן צִמְצֵם הַשֵּׁם יִתְבָּרַךְ אוֹר הָאֱמֶת וְהִסְתִּיר וְהִצְפִּין וְהִלְבִּישׁ אוֹר הָאֱמֶת וּמִעֲטוֹ בְּאֹפֶן שֶׁיּוּכְלוּ לְקַבְּלוֹ. וּמֵחֲמַת שֶׁמִּעֵט וְצִמְצֵם אוֹר הָאֱמֶת, שֶׁזֶּה בְּחִינַת מִעוּט הַיָּרֵחַ, עַל־כֵּן מִשָּׁם אֲחִיזַת כָּל הַסִּטְרָא־אָחֳרָא, שֶׁהִיא בְּחִינַת חשֶׁךְ וָשֶׁקֶר, שֶׁאֲחִיזָתָהּ רַק מִמִּעוּט אוֹר הַיָּרֵחַ, הַיְנוּ מִמִּעוּט וְצִמְצוּם אוֹר הָאֱמֶת, שֶׁמִּשָּׁם עִקַּר אֲחִיזַת הַשֶּׁקֶר שֶׁהוּא הַסִּטְרָא־אָחֳרָא. כִּי בְּוַדַּאי אִם לֹא הָיָה רַק עֶצֶם אוֹר הָאֱמֶת בְּעַצְמוֹ, בְּוַדַּאי לֹא הָיָה לְהַסִּטְרָא־אָחֳרָא שֶׁהוּא הַשֶּׁקֶר שׁוּם אֲחִיזָה, כִּי מֵאַחַר שֶׁהָיוּ הַכֹּל יוֹדְעִין עֶצֶם הָאֱמֶת - אֵיךְ הָיָה אֶפְשָׁר לְחַפּוֹת הָאֱמֶת וְלַהֲפֹךְ הָאֱמֶת לְשֶׁקֶר? כִּי בְּוַדַּאי מִי שֶׁיּוֹדֵעַ הָאֱמֶת לַאֲמִתּוֹ, אִי אֶפְשָׁר לְהַטְעוֹתוֹ בְּשׁוּם שֶׁקֶר שֶׁבָּעוֹלָם; אַךְ מֵאַחַר שֶׁנִּתְמַעֵט וְנִתְצַמְצֵם הָאֱמֶת, אַף־עַל־פִּי שֶׁעֲדַיִן הוּא אֱמֶת גָּמוּר, עִם־כָּל־זֶה כְּבָר יֵשׁ לָהֶם אֵיזֶה אֲחִיזָה, מֵאַחַר שֶׁאֵין יוֹדְעִין עֶצֶם הָאֱמֶת, רַק שֶׁרוֹאִין הָאֱמֶת מֵרָחוֹק דֶּרֶךְ כַּמָּה חַלּוֹנוֹת וּלְבוּשִׁין, עַל־יְדֵי־זֶה יֵשׁ לָהֶם אֲחִיזָה לְהַטְעוֹת וּלְחַפּוֹת הָאֱמֶת בְּשֶׁקֶר וְלַהֲפֹךְ הַשֶּׁקֶר לֶאֱמֶת, חַס וְשָׁלוֹם. וְעַל־כֵּן עִקַּר עֲבוֹדָתֵנוּ וִיגִיעָתֵנוּ לְמַלֹּאת פְּגִימַת הַלְּבָנָה, הַיְנוּ לְבָרֵר הָאֱמֶת מִן הַשֶּׁקֶר. וְעַל־ כֵּן עִקַּר הָעֵצָה וְהַתַּקָּנָה בִּכְלָלִיּוּת הָעֲבוֹדָה שֶׁאָנוּ צְרִיכִין בְּזֶה הָעוֹלָם, הָעִקָּר הוּא רַק אֱמֶת, דְּהַיְנוּ שֶׁלֹּא לְהַטְעוֹת אֶת עַצְמוֹ, חַס וְשָׁלוֹם, רַק לְהִסְתַּכֵּל בְּכָל דָּבָר עַל הָאֱמֶת לַאֲמִתּוֹ, וּלְהִשְׁתַּדֵּל בִּתְפִלָּתוֹ, שֶׁאֲפִלּוּ אִם אֵינוֹ יָכוֹל לְהִתְפַּלֵּל כְּלָל, עַל־כָּל־פָּנִים יִרְאֶה שֶׁיּוֹצִיא הַדִּבּוּר מִפִּיו בֶּאֱמֶת לְפִי מַדְרֵגָתוֹ; וְאַף־עַל־פִּי שֶׁעֲדַיִן אֵין הָאֱמֶת בָּרוּר וָזַךְ, עִם־כָּל־זֶה מֵאַחַר שֶׁחָפֵץ בָּאֱמֶת וּמוֹשֵׁךְ עַצְמוֹ רַק אֶל הָאֱמֶת וּמַכְרִיחַ עַצְמוֹ לְדַבֵּר דִּבּוּרֵי אֱמֶת, עַל־כֵּן זֶה הָאֱמֶת הוּא עַל־כָּל־ פָּנִים בִּבְחִינַת חַלּוֹן וְיוּכַל אַחֵר לְהָאִיר בּוֹ, דְּהַיְנוּ הַצַּדִּיקֵי־אֱמֶת, שֶׁהֵם נֶגְדֵּנוּ בִּבְחִינַת עֶצֶם הָאֱמֶת, וְהֵם מְאִירִים בְּכָל תְּפִלּוֹת יִשְׂרָאֵל וּמַעֲלִים אוֹתָם כְּפִי הָאֱמֶת שֶׁבְּכָל תְּפִלָּה שֶׁל כָּל אֶחָד שֶׁהוּא בִּבְחִינַת חַלּוֹן עַל־כָּל־פָּנִים; וּכְפִי בְּהִירוּת וְצַחוּת הַחַלּוֹן, דְּהַיְנוּ הַדִּבּוּר אֱמֶת, כֵּן הַצַּדִּיק שֶׁהוּא עֱצֶם הָאֱמֶת יוּכַל לְהָאִיר בּוֹ (שם אותיות ז ח). 
מג. עִקַּר הַגְּאֻלָּה הוּא עַל־יְדֵי אֱמֶת, שֶׁהוּא מְשִׁיחַ צִדְקֵנוּ שֶׁיָּבוֹא בִּמְהֵרָה בְיָמֵינוּ, שֶׁנִּקְרָא אֱמֶת, כְּמוֹ שֶׁכָּתוּב: "שְׁלַח אוֹרְךָ וַאֲמִתְּךָ וְגוֹ'", וּפֵרְשׁוֹ רַשִׁ"י עַל מָשִׁיחַ, כִּי עִקַּר בִּיאַת הַמָּשִׁיחַ הוּא לְגַלּוֹת הָאֱמֶת בָּעוֹלָם, כִּי עַכְשָׁו הָאֱמֶת בְּגָלוּת גָּדוֹל וְהָאֱמֶת נַעֲשֶׂה עֲדָרִים עֲדָרִים וְכָל אֶחָד אוֹמֵר שֶׁאֶצְלוֹ הָאֱמֶת, וְעִקַּר הָאֱמֶת יִתְגַּלֶּה עַל־יְדֵי מָשִׁיחַ, כְּמוֹ שֶׁכָּתוּב: "שְׂפַת אֱמֶן תִּכּוֹן לָעַד וְגוֹ'", וְדָרְשׁוּ רַבּוֹתֵינוּ זַ"ל: "כּוֹנַנְתָּ" לֹא כְתִיב וְכוּ', וְזֶה עִקַּר הַגְּאֻלָּה (שם

). 
מו. אֵין שְׁתֵּי נְשָׁמוֹת שָׁווֹת בָּעוֹלָם בְּמַדְרֵגָתָן, רַק אֶחָד גָּדוֹל מֵחֲבֵרוֹ. וְעִקַּר הַחִלּוּק וְהַמַּעֲלָה שֶׁבֵּין הַנְּשָׁמוֹת הוּא רַק בִּבְחִינַת הֶאָרַת הָאֱמֶת הַנַּ"ל; כִּי הַנְּשָׁמָה נִקְרֵאת אוֹר, כְּמוֹ שֶׁכָּתוּב: "נֵר ה' נִשְׁמַת אָדָם", וְעִקַּר אוֹר הַנְּשָׁמָה הוּא אֱמֶת, שֶׁהוּא עִקַּר אוֹר הַמֵּאִיר. וְכָל נְשָׁמָה שֶׁיֵּשׁ לָהּ אֱמֶת בְּיוֹתֵר - הִיא גְדוֹלָה בְּיוֹתֵר וּמְאִירָה בְּיוֹתֵר, וְהַקָּטָן צָרִיךְ לְקַבֵּל מֵהַגָּדוֹל מִמֶּנּוּ, כִּי כָל הַנְּשָׁמוֹת מְקַבְּלִין זֶה מִזֶּה מִמַּדְרֵגָה לְמַדְרֵגָה (שם). 
מז. בְּוַדַּאי בְּזֶה הָעוֹלָם לָאו כָּל אָדָם זוֹכֶה לִבְחִינַת אֱמֶת הַבָּרוּר לְגַמְרֵי בִּשְׁלֵמוּת, אַךְ הָעִקָּר כָּל זְמַן שֶׁשּׁוֹמְרִין הָאֱמֶת שֶׁלֹּא יִתְהַפֵּךְ לְשֶׁקֶר, חַס וְשָׁלוֹם, רַק מִסְתַּכְּלִין עַל נְקֻדַּת הָאֱמֶת לַאֲמִתּוֹ, אֲזַי אַף־עַל־פִּי שֶׁאֵין זוֹכִין עֲדַיִן לָאֱמֶת הַבָּרוּר לְגַמְרֵי, לִבְחִינַת עֶצֶם הָאֱמֶת, אַף־עַל־פִּי־כֵן יָכוֹל אַחֵר לְהָאִיר בּוֹ עַל־כָּל־פָּנִים, וִיכוֹלִין עַל־יְדֵי־זֶה גַּם־כֵּן לָצֵאת מֵחשֶׁךְ לְאוֹר (שם

). 
פ. צִיצִת וּתְפִלִּין הֵם בְּחִינַת אוֹר הָאֱמֶת כַּמְבֹאָר בִּפְנִים, וְעִקַּר מִצְוָתָם בַּיּוֹם, אֲבָל בַּלַּיְלָה שֶׁאָז תַּרְעֵי דְּגַן־עֵדֶן סְתִימִין וְהַחשֶׁךְ מִתְגַּבֵּר, וְאָז אֵין זְמַן צִיצִת וּתְפִלִּין, כִּי יֵשׁ חשֶׁךְ בְּחִינַת שֶׁקֶר, שֶׁאִי אֶפְשָׁר לְהַגִּיעַ לְשָׁם אוֹר הַצִּיצִת וּתְפִלִּין, וְאָז אֵין תַּקָּנָה כִּי־אִם עַל־יְדֵי הַדִּבּוּר־אֱמֶת, שֶׁזֶּה בְּחִינַת תְּפִלַּת־עַרְבִית שֶׁתִּקֵּן יַעֲקֹב אָבִינוּ דַּיְקָא, שֶׁהוּא עֶצֶם הָאֱמֶת, בְּחִינַת "תִּתֵּן אֱמֶת לְיַעֲקֹב"; וְהוּא הָיָה חָזָק בְּהָאֱמֶת כָּל־כָּךְ, עַד שֶׁהֵאִיר הָאֱמֶת גַּם בְּתֹקֶף חֶשְׁכַת לַיְלָה בְּהִתְגַּבְּרוּת הַחשֶׁךְ וְהַשֶּׁקֶר מְאֹד מְאֹד. וְעַל־ כֵּן תִּקֵּן תְּפִלַּת־עַרְבִית כְּשֶׁבָּרַח מֵעֵשָׂו הָרָשָׁע וְהָלַךְ לְלָבָן הָאֲרַמִּי, שֶׁשְּׁנֵיהֶם בְּחִינַת חשֶׁךְ עָצוּם וְנוֹרָא מְאֹד, וְרָאָה שֶׁהַחשֶׁךְ סְבָבוּהוּ מִכָּל צַד וּמִצִּדֵּי צְדָדִים, וְאָז דַּיְקָא הִתְגַּבֵּר וְתִקֵּן תְּפִלַּת־עַרְבִית, שֶׁעִקַּר תִּקּוּן הַתְּפִלָּה הוּא אֱמֶת, לְהוֹרוֹת שֶׁבְּתֹקֶף הָאֱמֶת שֶׁלּוֹ יָכוֹל לְהָאִיר גַּם בְּחֶשְׁכַת לָיְלָה. וְעַל־כֵּן זָכָה שֶׁהָיְתָה מִטָּתוֹ שְׁלֵמָה בִּבְחִינַת "כֻּלּוֹ זֶרַע אֱמֶת" - הֵפֶךְ יִשְׁמָעֵאל וְעֵשָׂו שֶׁהֵם זֶרַע שֶׁקֶר. וְזֶהוּ שֶׁאוֹמְרִים בַּלַּיְלָה קֹדֶם הַשֵּׁנָה: "בְּיָדְךָ אַפְקִיד רוּחִי, פָּדִיתָה אוֹתִי ה' אֵל אֱמֶת", כִּי בְּתֹקֶף חֶשְׁכַת לַיְלָה צְרִיכִין לְדַבֵּק אֶת עַצְמוֹ אֶל הָאֱמֶת בְּיוֹתֵר. וְעַל־כֵּן תְּפִלַּת־ עַרְבִית שֶׁתִּקֵּן יַעֲקֹב אָבִינוּ - בְּחִינַת עֶצֶם הָאֱמֶת, הוּא רְשׁוּת דַּיְקָא, כִּי עִקַּר תִּקּוּן הַתְּפִלָּה הוּא עַל־יְדֵי אֱמֶת כַּנַּ"ל. אֲבָל בְּתֹקֶף חֶשְׁכַת הַגָּלוּת אִי אֶפְשָׁר לְבָאֵר וּלְפָרֵשׁ הָאֱמֶת, רַק שֶׁכָּל אֶחָד צָרִיךְ לִפְנוֹת אֶל הָאֱמֶת כְּפִי מַה שֶּׁהוּא, בִּבְחִינַת "וְדוֹבֵר אֱמֶת בִּלְבָבוֹ", שֶׁזֶּהוּ בְּחִינַת רְשׁוּת, שֶׁאֵין הָאֱמֶת קָבוּעַ, רַק הַכֹּל כְּפִי הָעִנְיָן וְהַשָּׁעָה, וְכָל אֶחָד כְּפֻם מַה דִּמְשַׁעֵר בְּלִבֵּהּ. וְעַל־כֵּן כְּשֶׁנִּפְסְקָה הַהֲלָכָה 'תְּפִלַּת עַרְבִית - רְשׁוּת', נִתּוֹסְפוּ כַּמָּה מֵאוֹת סַפְסְלֵי בְּבֵית־הַמִּדְרָשׁ כְּמוֹ שֶׁאָמְרוּ רַבּוֹתֵינוּ זַ"ל, כִּי עַל־יְדֵי בְּחִינַת 'תְּפִלַּת עַרְבִית רְשׁוּת', שֶׁתִּקֵּן יַעֲקֹב אָבִינוּ שֶׁהוּא עֶצֶם הָאֱמֶת שֶׁמֵּאִיר בְּתֹקֶף הַחשֶׁךְ לְכָל אֶחָד כְּפִי מַה שֶּׁהוּא בְּאוֹתָהּ הַשָּׁעָה, עַל־יְדֵי־זֶה יְכוֹלִין לְהִתְקָרֵב הַכֹּל לְהַשֵּׁם יִתְבָּרַךְ וּלְהַתּוֹרָה הַקְּדוֹשָׁה, כִּי אֵין שׁוּם חשֶׁךְ שֶׁיַּחְשִׁיךְ לָהֶם, כִּי הוּא מֵאִיר לָהֶם עַל־יְדֵי עֹצֶם אֲמִתָּתוֹ עַד שֶׁמְּקָרֵב כֻּלָּם לְהַשֵּׁם יִתְבָּרַךְ, שֶׁזֶּה בְּחִינַת הַתַּלְמִידִים רַבִּים שֶׁנִּתּוֹסְפוּ אָז (שם אותיות טו, כב). 
פא. עִקַּר הִתְגַּבְּרוּת הַשֶּׁקֶר וְהָרַע וְהַחשֶׁךְ הוּא בְּעִנְיַן הַזִּוּוּג וְהַפַּרְנָסָה, כִּי דַּיְקָא מֵחֲמַת שֶׁיֵּשׁ בָּהֶם קְדֻשָּׁה גְבוֹהָה מְאֹד וְהֵם בִּבְחִינַת אֱמֶת, עַל־כֵּן מִתְגַּבְּרִים הָרַע וְהַשֶּׁקֶר לְהַעְלִים הַקְּדֻשָּׁה וְעֶצֶם הָאֱמֶת שֶׁיֵּשׁ בָּזֶה לְגַמְרֵי. וְעִקַּר הַתִּקּוּן לָזֶה הוּא עַל־יְדֵי הַצַּדִּיק־אֱמֶת, שֶׁמֵּאִיר נְקֻדַּת הָאֱמֶת בְּלֵב כָּל אֶחָד מִיִּשְׂרָאֵל, שֶׁיִּמְשֹׁךְ עַצְמוֹ בְּכָל עֵת רַק אֶל נְקֻדַּת הָאֱמֶת לַאֲמִתּוֹ; וְעַל־יְדֵי־זֶה זוֹכִין לָצֵאת מִתּוֹךְ הַחשֶׁךְ לְאוֹר גָּדוֹל, וְזוֹכִין לְזִוּוּג וּפַרְנָסָה בִּקְדֻשָּׁה גְדוֹלָה (שם אותיות כה, לא; ועיין ברית,

). 
פד. עַל־יְדֵי צְדָקָה עוֹלִין וּמִתְקַדְּשִׁין מִטֻּמְאַת הַשֶּׁקֶר לְתַכְלִית הַקְּדֻשָּׁה, שֶׁהוּא בְּחִינַת קֹדֶשׁ (שם הלכות קידושין, הלכה ה). 
פה. עִקַּר תִּקּוּן שְׁלֵמוּת הָעֵצָה לֵידַע בְּאֵיזֶה דֶּרֶךְ לֵילֵךְ, הוּא עַל־יְדֵי הָאֱמֶת, הַיְנוּ שֶׁיִּמְשֹׁךְ עַצְמוֹ רַק אֶל הָאֱמֶת לַאֲמִתּוֹ וּלְבַקֵּשׁ מֵהַשֵּׁם יִתְבָּרַךְ שֶׁיּוֹלִיכֵהוּ וְיַדְרִיכֵהוּ בְּדֶרֶךְ הָאֱמֶת (שם הל' גיטין, הל' ג,

). 
ח. מְבֹאָר בִּכְתָבִים שֶׁמַּלְכוּת שֶׁהוּא בְּחִינַת מַדְרֵגָה אַחֲרוֹנָה שֶׁל עוֹלָם הָעֶלְיוֹן, כְּגוֹן מַלְכוּת דִּבְרִיאָה, הוּא לְמַעְלָה וְהוּא שֹׁרֶשׁ כָּל בְּחִינַת עַתִּיק שֶׁהוּא מַדְרֵגָה הָעֶלְיוֹנָה שֶׁבָּעוֹלָם הַתַּחְתּוֹן מִמֶּנּוּ, בְּחִינַת עַתִּיק דִּיצִירָה, וְכֵן מֵעוֹלָם לְעוֹלָם. וּמַלְכוּת הוּא בְּחִינַת אֱמוּנָה, וְעַתִּיק שֶׁהוּא לְמַעְלָה וְשֹׁרֶשׁ כָּל הַמֹּחִין שֶׁבְּאוֹתוֹ עוֹלָם, הוּא בְּחִינַת דְּבֵקוּת נִפְלָא וְנוֹרָא לְהַשֵּׁם יִתְבָּרַךְ, בְּחִינַת רַעֲוָא דְּרַעֲוִין, רָצוֹן שֶׁבָּרְצוֹנוֹת, שֶׁהוּא בְּחִינַת הַדְּבֵקוּת הַנִּפְלָא וְהַנּוֹרָא לְהַשֵּׁם יִתְבָּרַךְ, בְּחִינַת "צָמְאָה לְךָ נַפְשִׁי וְגוֹ'", שֶׁזֶּה בְּחִינַת הַדְּבֵקוּת שֶׁל הַתְּפִלִּין, בְּחִינַת "שִׂימֵנִי כַחוֹתָם עַל לִבֶּךָ וְגוֹ' כִּי עַזָּה כַמָּוֶת אַהֲבָה... רְשָׁפֶיהָ רִשְׁפֵּי אֵשׁ וְגוֹ'" - אַשְׁרֵי הַזּוֹכֶה לָזֶה. אֲבָל הַדְּבֵקוּת הַזֹּאת שֶׁבְּאוֹתוֹ עוֹלָם וּמַדְרֵגָה הוּא לְמַטָּה מִבְּחִינַת מַלְכוּת, בְּחִינַת אֱמוּנָה שֶׁל מַדְרֵגָה וְעוֹלָם הַגָּבֹהַּ יוֹתֵר כַּנַּ"ל. עַל־כֵּן עִקַּר הַהַתְחָלָה הוּא אֱמוּנָה, וְהַסּוֹף הוּא דְּבֵקוּת וֶאֱמוּנָה שֶׁל מַעְלָה; כְּגוֹן לְמָשָׁל בְּעוֹלַם הָעֲשִׂיָּה, בְּוַדַּאי הַתְחָלַת עֲבוֹדַת יִשְׂרָאֵל הוּא אֱמוּנָה, וְעַל־יְדֵי־זֶה זוֹכֶה לֵילֵךְ מִדַּרְגָּא לְדַרְגָּא עַד שֶׁמַּגִּיעַ לִבְחִינַת עַתִּיק שֶׁבַּעֲשִׂיָּה, שֶׁהוּא בְּחִינַת רָצוֹן וּדְבֵקוּת, בְּחִינַת שֹׁרֶשׁ הַמֹּחִין שֶׁבַּעֲשִׂיָּה, וְעַל־יְדֵי מֹחִין וּדְבֵקוּת אֵלּוּ זוֹכֶה לָבוֹא לִבְחִינַת אֱמוּנָה שֶׁבָּעוֹלָם הַגָּבֹהַּ מִמֶּנּוּ, בְּחִינַת מַלְכוּת אֱמוּנָה שֶׁבִּיצִירָה; וְאַחַר־כָּךְ הוּא עוֹלֶה עוֹד מִדַּרְגָּא לְדַרְגָּא עַד שֶׁמַּשִּׂיג בְּחִינַת עַתִּיק שֶׁבִּיצִירָה וֶאֱמוּנָה שֶׁבִּבְרִיאָה, וְכֵן מֵעוֹלָם לְעוֹלָם; כִּי אֱמוּנָה בְּחִינַת מַלְכוּת שֶׁל עוֹלָם הָעֶלְיוֹן הוּא שֹׁרֶשׁ הַחַיּוּת שֶׁל בְּחִינַת עַתִּיק, שֶׁהוּא בְּחִינַת שֹׁרֶשׁ הַמֹּחִין שֶׁבָּעוֹלָם הַתַּחְתּוֹן מִמֶּנּוּ, וְהַמֹּחִין אֵלּוּ הֵם הַחַיּוּת שֶׁל בְּחִינַת מַלְכוּת וֶאֱמוּנָה שֶׁבְּזֶה הָעוֹלָם וְהַמַּדְרֵגָה (שם). 
ט. עַצְבוּת וְעַצְלוּת וּכְבֵדוּת נִמְשָׁךְ מֵהָרַע שֶׁבִּיסוֹד הֶעָפָר שֶׁהוּא עִקַּר נְשִׁיכַת הַנָּחָשׁ, בְּחִינַת "וְנָחָשׁ עָפָר לַחְמוֹ"; וְהַכְנָעָתוֹ עַל־יְדֵי יְסוֹד הֶעָפָר שֶׁבַּקְּדֻשָּׁה, שֶׁהוּא בְּחִינַת אֱמוּנָה (שם

). 
יט. עִקַּר הַטֻּמְאָה הוּא בְּחִינַת חֲקִירוֹת הַמְחַקְּרִים וְהַכּוֹפְרִים, שֶׁהֵם זֻהֲמַת הַנָּחָשׁ, סִטְרָא דְּמוֹתָא (שם יט). 
כ. בַּדּוֹרוֹת הָרִאשׁוֹנִים הָיָה כָּל הַכְּפִירוֹת עַל־פִּי דַּרְכֵי עֲבוֹדוֹת זָרוֹת שֶׁלָּהֶם, וּמֵעֵת שֶׁנִּתְבַּטֵּל הַיֵּצֶר הָרָע שֶׁל עֲבוֹדָה זָרָה, הִתְגַּבֵּר הַיֵּצֶר הָרָע שֶׁל פִילוֹסוֹפְיָא שֶׁהֵם כְּפִירוֹת שֶׁל חַכְמֵי הַטֶּבַע שֶׁמַּכְנִיסִין כְּפִירוֹת עַל־פִּי חָכְמָתָם הָרָעָה, וּבֶאֱמֶת הַכֹּל אֶחָד כַּמְבֹאָר בִּפְנִים (שם הלכות קריאתשׂה
